recs=[]
recs.append(R(9740595,"4 اجزاء والی گواکامولے کی ترکیب",
"4 اجزاء والی گواکامولے کی ترکیب جو آپ 5 منٹ یا اس سے کم میں تیار کر سکتے ہیں!",
"6 سرونگ","1 سرونگ",
["3 پکے ہوئے ایووکاڈو","2 کھانے کے چمچ ایکسٹرا چنکی سالسا، مجھے میڈیم یا تیز پسند ہے","1 کھانے کا چمچ لائم کا رس، تقریباً آدھے تازہ نچوڑے ہوئے لائم کا","½ چائے کا چمچ سمندری نمک یا حسبِ ذائقہ","¼ چائے کا چمچ لہسن پاؤڈر، اختیاری"],
["اپنے ایووکاڈو آدھے کاٹیں اور گٹھلیاں نکال دیں۔ پھر چمچ سے گودا مکسنگ پیالے میں نکال لیں۔ بڑے کانٹے یا آلو مسلنے والے آلے سے ایووکاڈو کو زیادہ مسلے بغیر مسل لیں۔ اگر آپ کو زیادہ بناوٹ پسند ہے تو کچھ موٹے ٹکڑے رہنے دیں۔",
"باقی اجزاء ڈالیں اور ملانے کے لیے ہلائیں۔",
"ویگن ٹیکوز، ناچوز، بریٹوز یا چپس کے ساتھ پیش کریں۔"],
["بہترین ذائقے اور بناوٹ کے لیے بہت پکے ہوئے ایووکاڈو استعمال کریں۔","اپنے ایووکاڈو کو زیادہ نہ مسلیں۔ ہاتھ سے مسلیں، بلینڈر یا فوڈ پروسیسر سے نہیں، ورنہ بہت ہموار ہو جائے گا۔ میرا خیال ہے کہ بہترین گواکامولے میں کچھ موٹے ٹکڑے ثابت رہتے ہیں۔","اپنی پسندیدہ سالسا استعمال کریں جس میں سب سے زیادہ ذائقہ ہو۔ چونکہ ہم تازہ ٹماٹر اور ہالاپینو استعمال نہیں کر رہے، آپ کو یقینی بنانا ہوگا کہ آپ کی سالسا اچھے معیار کی ہو۔ مجھے چنکی میڈیم سالسا پسند ہے لیکن آپ اپنی مطلوبہ تیزی کی سطح استعمال کریں۔","ذائقے اپنی پسند کے مطابق ٹھیک کریں۔ کسی بھی ترکیب کی طرح، مسالے اپنی پسند کے مطابق ٹھیک کریں۔ ایووکاڈو کا سائز مختلف ہوتا ہے اس لیے پیش کرنے سے پہلے اپنی گواکامولے چکھیں اور ضرورت ہو تو مزید نمک یا لائم کا رس ڈالیں۔","بچا ہوا فریج میں رکھیں، پلاسٹک ریپ براہِ راست اپنی گواکامولے کے اوپر رکھ کر تاکہ وہ 2-3 دن بھورا نہ ہو۔"],[]))
recs.append(R(9741235,"بہترین ویگن گرلڈ چیز",
"بہترین ویگن گرلڈ چیز سینڈوچ جس میں کھنچنے والا \"پنیر\" اور ٹماٹر اور ایووکاڈو کے قتلے ہیں۔ یہ لذیذ، آرام دہ اور فوراً تیار ہے۔",
"3 سینڈوچ","1 سرونگ",
["1/4 کپ کچے کاجو","1 کھانے کا چمچ ٹیپیوکا اسٹارچ","1 کھانے کا چمچ نیوٹریشنل ییسٹ","1.5 چائے کے چمچ سیب کا سرکہ","1/4 چائے کا چمچ سمندری نمک","1/2 کپ پانی","6 قتلے ثابت اناج کی کٹی ہوئی ڈبل روٹی (یا اپنی پسند کی)","1-2 کھانے کے چمچ ویگن مکھن (اختیاری)","ٹماٹر کے قتلے (اختیاری)","ایووکاڈو کے قتلے (اختیاری)"],
["کیتلی میں یا اپنے چولہے پر کچھ پانی ابالیں اور کاجو کو گرم پانی میں 20 منٹ بھگو دیں۔ پھر انہیں چھان لیں۔",
"پھر اپنی ڈبل روٹی ٹوسٹر میں ٹوسٹ کریں، اور اگر استعمال کر رہے ہیں تو ہر قتلے پر مکھن لگائیں۔ یا آپ کاسٹ آئرن پین یا اسکیلیٹ پر مکھن سے چکنائی لگا کر چولہے پر ڈبل روٹی ٹوسٹ کر سکتے ہیں۔ الگ رکھ دیں۔",
"پنیر کے تمام اجزاء، اب چھانے ہوئے کاجو سمیت، اپنے بلینڈر میں ڈالیں اور ہموار ہونے تک پروسیس کریں۔",
"پھر مائع آمیزہ اپنے چولہے پر پین میں ڈالیں اور آمیزے کو گاڑھا اور کھنچنے والا ہونے تک دھیمی آنچ پر پکائیں، بار بار ہلاتے رہیں۔ یہ تقریباً 2-4 منٹ میں مائع سے پگھلی ہوئی، پنیر جیسی بناوٹ میں بدل جائے گا۔",
"پنیر کو 3 سینڈوچز میں تقسیم کریں اور اگر استعمال کر رہے ہیں تو ٹماٹر اور ایووکاڈو کے قتلے ڈالیں۔ پنیر کے گرم ہوتے ہی فوراً پیش کریں۔ اگر وہ آپ کے تیار کرنے سے پہلے ٹھنڈا ہو جائے تو جمع کیے ہوئے سینڈوچز کو دونوں طرف دوبارہ گرم کرنے کے لیے پین میں واپس رکھ دیں۔"],[],[]))
